// The groom's newest post. Only new ones go to Claude, so the check costs nothing on a quiet day.
const S = $('Trev settings').first().json;
const store = $getWorkflowStaticData('global');
const posts = $input.all().map(i => i.json).filter(p => p && (p.shortCode || p.id));
posts.sort((a, b) => String(b.timestamp).localeCompare(String(a.timestamp)));
const p = posts[0];
if (!p || store.lastPost === (p.shortCode || p.id) || store.engaged) return [{ json: { fresh: false } }];
store.lastPost = p.shortCode || p.id;
return [{ json: { fresh: true, caption: p.caption || '', image: p.displayUrl || (p.images || [])[0] || '', url: p.url } }];

// Claude looks at the photo itself, so "engaged" never relies on a hashtag.
const S = $('Trev settings').first().json;
const p = $input.first().json;
const ask = `This is a new Instagram post from ${S.GROOM.name}. Caption: "${p.caption}".
Is this an engagement announcement? Look for a ring on a hand, a proposal, or the caption saying so.
Reply with JSON only: {"engaged": true or false, "ring": true or false, "why": "under 12 words"}`;
return [{ json: { body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: [
  { type: 'image', source: { type: 'url', url: p.image } },
  { type: 'text', text: ask } ] }] } } }];

const textOf = (node) => {
  const t = ($(node).first().json.content || []).map(c => c.text || '').join('').trim();
  if (!t) throw new Error(node + ' returned no text. Raise max_tokens or check the model name.');
  return t;
};
const jsonOf = (node) => {
  const t = textOf(node);
  const m = t.match(/\{[\s\S]*\}/);
  if (!m) throw new Error(node + ' did not return JSON: ' + t.slice(0, 120));
  return JSON.parse(m[0]);
};

const v = jsonOf('Claude: is that a ring?');
return [{ json: { engaged: v.engaged === true, ring: v.ring === true, why: String(v.why || '') } }];

// Apify's tagged posts -> the same shape the demo uses: { year, tagged: [handles] }.
const S = $('Trev settings').first().json;
const photos = $input.all().map(i => i.json).filter(p => p && p.timestamp).map(p => ({
  year: new Date(p.timestamp).getFullYear(),
  tagged: [S.GROOM.instagram, (p.ownerUsername || ''), ...((p.taggedUsers || []).map(u => u.username || u))]
    .filter((h, i, a) => h && a.indexOf(h) === i) }));
const people = {};
for (const p of $input.all().map(i => i.json)) {
  if (p.ownerUsername) people[p.ownerUsername] = { name: p.ownerFullName || p.ownerUsername };
  for (const u of p.taggedUsers || []) if (u.username) people[u.username] = { name: u.full_name || u.username };
}
return [{ json: { photos, people } }];

const S = $('Trev settings').first().json;
const { photos, people } = $input.first().json;
const counts = {};
for (const ph of photos) for (const t of ph.tagged) if (t !== S.GROOM.instagram) counts[t] = (counts[t] || 0) + 1;
const all = Object.entries(counts).map(([handle, n]) => ({ handle, n, name: (people[handle] || {}).name || handle,
  family: ((people[handle] || {}).name || '').toLowerCase().endsWith(' ' + S.GROOM.surname.toLowerCase()) }));
const family = all.filter(p => p.family);
const mates = all.filter(p => !p.family && p.n >= S.MIN_TAGS).sort((a, b) => b.n - a.n)
  .slice(0, Math.max(0, S.GUEST_LIST_SIZE - 1 - family.length));
const guests = [...mates, ...family];
$getWorkflowStaticData('global').guests = guests;
const msg = `💍 <b>${S.GROOM.name} just got engaged.</b>\n🔎 ${photos.length} tagged photos scanned.\n\n🧾 <b>Guest list (${guests.length + 1})</b>\n`
  + guests.map(g => `• ${g.name} · instagram.com/${g.handle}${g.family ? ' (family)' : ''}`).join('\n')
  + `\n\nInstagram doesn't let bots message people, so add them to the bucks group yourself. Trev takes it from there.`;
return [{ json: { guests, msg } }];

// Real forecast for the villa (Open-Meteo, free, no key), so the plan fits the surf and the weather.
const S = $('Trev settings').first().json;
const w = $('Weather at the villa').first().json.daily || {};
const m = ($('Surf at the villa').first().json.daily) || {};
const days = (w.time || []).slice(0, 3).map((d, i) => ({ day: i + 1,
  maxC: Math.round((w.temperature_2m_max || [])[i]), rainPct: (w.precipitation_probability_max || [])[i],
  windKmh: Math.round((w.wind_speed_10m_max || [])[i]), waveM: (m.wave_height_max || [])[i] }));
const ask = `You're Trev, the AI planning ${S.GROOM.name}'s bucks: ${S.GUEST_LIST_SIZE} blokes, ${S.TRIP.where}, ${S.TRIP.dates}, staying at ${S.VILLA.name}.
The forecast for the three days: ${JSON.stringify(days)}.
Write the itinerary as exactly 3 lines, one per day, like "Day 1 · Surf 🏄 3ft and clean, then beers 🍻".
It MUST have a surf session, 18 holes of golf, and beers every day. Rain doesn't cancel anything, these blokes play in the wet.
Put the surf on the day with the biggest waves. Mention the real wave size once. Under 12 words a line. No other text.`;
return [{ json: { days, body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: ask }] } } }];

const textOf = (node) => {
  const t = ($(node).first().json.content || []).map(c => c.text || '').join('').trim();
  if (!t) throw new Error(node + ' returned no text. Raise max_tokens or check the model name.');
  return t;
};
const jsonOf = (node) => {
  const t = textOf(node);
  const m = t.match(/\{[\s\S]*\}/);
  if (!m) throw new Error(node + ' did not return JSON: ' + t.slice(0, 120));
  return JSON.parse(m[0]);
};

const S = $('Trev settings').first().json;
const plan = textOf('Claude: the itinerary');
return [{ json: { plan, msg: `🗓️ <b>${S.GROOM.name}'s bucks · ${S.TRIP.where} · ${S.TRIP.dates}</b>\n\n${plan}\n\nOne vote each. Lock in or miss out.` } }];

// One Overpass query (OpenStreetMap, free, no key): pubs and bars near the villa, plus golf courses.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const q = `[out:json][timeout:25];(node["amenity"~"^(pub|bar|biergarten)$"](around:2500,${v.lat},${v.lng});`
  + `way["leisure"="golf_course"](around:15000,${v.lat},${v.lng});node["cuisine"~"kebab"](around:4000,${v.lat},${v.lng}););out center 80;`;
return [{ json: { q } }];

const km = (a, b, c, d) => { const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 + Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x)); };

// Tee off at the closest course, then a pub crawl that never walks back on itself.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const els = ($input.first().json.elements || []).map(e => ({ name: (e.tags || {}).name, tags: e.tags || {},
  lat: e.lat || (e.center || {}).lat, lng: e.lon || (e.center || {}).lon })).filter(e => e.name && e.lat);
const golf = els.filter(e => e.tags.leisure === 'golf_course').map(e => ({ ...e, km: km(v.lat, v.lng, e.lat, e.lng) }))
  .sort((a, b) => a.km - b.km)[0];
let pubs = els.filter(e => /pub|bar|biergarten/.test(e.tags.amenity || ''));
const route = [];
let here = { lat: v.lat, lng: v.lng }, walk = 0;
while (route.length < 4 && pubs.length) {
  pubs.sort((a, b) => km(here.lat, here.lng, a.lat, a.lng) - km(here.lat, here.lng, b.lat, b.lng));
  const next = pubs.shift();
  walk += km(here.lat, here.lng, next.lat, next.lng);
  route.push(next.name); here = next;
}
const kebab = els.filter(e => /kebab/i.test(e.tags.cuisine || '')).map(e => ({ name: e.name, lat: e.lat, lng: e.lng,
  km: km(v.lat, v.lng, e.lat, e.lng) })).sort((a, b) => a.km - b.km)[0] || null;
const msg = `🛬 <b>Wheels down. Trev's itinerary is live.</b>\n\n`
  + `⛳ 7:40am · 18 holes at ${golf ? golf.name : 'the closest course'}${golf ? ` (${golf.km.toFixed(1)} km)` : ''}\n`
  + `🍻 Then the crawl: ${route.join(' → ') || 'the closest pub'}\n`
  + `🚶 ${walk.toFixed(1)} km all up. Golf beers stay cold.`;
return [{ json: { golf, route, walk, kebab, msg } }];

const S = $('Trev settings').first().json;
const today = DateTime.now().setZone(S.TIMEZONE).toISODate();
const start = S.TRIP.start, end = DateTime.fromISO(start).plus({ days: S.TRIP.nights }).toISODate();
const crawl = $('Plan the crawl').first().json;
const w = $('Weather today').first().json.daily || {};
const ask = `You're Trev, running ${S.GROOM.name}'s bucks in ${S.TRIP.where}. Today: ${Math.round((w.temperature_2m_max || [])[0])}C max,
${(w.precipitation_probability_max || [])[0]}% rain, waves ${(($('Surf today').first().json.daily || {}).wave_height_max || [])[0]}m.
Golf: ${crawl.golf ? crawl.golf.name : 'closest course'}. Pub crawl: ${crawl.route.join(' -> ')}.
Write today's plan for the group chat in 3 short lines with times. Always 18 holes in the morning, then the crawl. Plain text only: no markdown, no asterisks, no other text.`;
return [{ json: { onTrip: today >= start && today <= end, body: { model: S.MODEL, max_tokens: 1500,
  messages: [{ role: 'user', content: ask }] } } }];

const textOf = (node) => {
  const t = ($(node).first().json.content || []).map(c => c.text || '').join('').trim();
  if (!t) throw new Error(node + ' returned no text. Raise max_tokens or check the model name.');
  return t;
};
const jsonOf = (node) => {
  const t = textOf(node);
  const m = t.match(/\{[\s\S]*\}/);
  if (!m) throw new Error(node + ' did not return JSON: ' + t.slice(0, 120));
  return JSON.parse(m[0]);
};

return [{ json: { msg: '🗓️ <b>Today</b>\n' + textOf('Claude: the day plan') } }];

// One vote each. Lock in (option 0) books that person, once, even if they tap twice.
const S = $('Trev settings').first().json;
const a = S.input.poll_answer;
const store = $getWorkflowStaticData('global');
store.votes = store.votes || {};
const id = String(a.user.id);
const isYes = (a.option_ids || [])[0] === 0;
const first = isYes && !store.votes[id];
if (isYes) store.votes[id] = { name: [a.user.first_name, a.user.last_name].filter(Boolean).join(' '), at: Date.now() };
const count = Object.keys(store.votes).length;
const villaNow = isYes && count >= Math.ceil(S.GUEST_LIST_SIZE / 2) && !store.villaBooked;
if (villaNow) store.villaBooked = true;
return [{ json: { book: first, name: (store.votes[id] || {}).name || a.user.first_name, count, villaNow } }];

const S = $('Trev settings').first().json;
const back = DateTime.fromISO(S.TRIP.start).plus({ days: S.TRIP.nights }).toISODate();
return [{ json: { body: { data: { cabin_class: 'economy', passengers: [{ type: 'adult' }], slices: [
  { origin: S.TRIP.fromAirport, destination: S.TRIP.toAirport, departure_date: S.TRIP.start },
  { origin: S.TRIP.toAirport, destination: S.TRIP.fromAirport, departure_date: back } ] } } } }];

// Duffel finds the cheapest fare. Trev doesn't spend anyone's money without them saying so.
const S = $('Trev settings').first().json;
const v = $('Count the vote').first().json;
const offers = ((($input.first().json || {}).data || {}).offers || []).sort((a, b) => +a.total_amount - +b.total_amount);
const o = offers[0];
const fare = o ? `${o.total_currency} ${Math.round(+o.total_amount)} return with ${o.owner.name}` : 'no fares found yet, Trev will retry';
return [{ json: { msg: `✅ <b>${v.name} is locked in</b> (${v.count}/${S.GUEST_LIST_SIZE}).\n✈️ Cheapest flight: ${fare}\n👕 ${S.GROOM.name}'s shirt is in the print queue.` } }];

// A Printful DRAFT order (confirm: false). Nothing is charged until you confirm it in Printful.
const S = $('Trev settings').first().json;
const v = $('Count the vote').first().json;
return [{ json: { body: { confirm: false, external_id: 'trev-' + Date.now(),
  recipient: { name: v.name, address1: S.VILLA.name, city: S.TRIP.where, country_code: 'AU' },
  items: [{ variant_id: S.SHIRT.variantId, quantity: 1, files: S.SHIRT.photoUrl ? [{ url: S.SHIRT.photoUrl }] : [] }] } } }];

const S = $('Trev settings').first().json;
const task = `Open ${S.VILLA.searchUrl}. Find a whole house that sleeps ${S.GUEST_LIST_SIZE} for ${S.TRIP.dates} (${S.TRIP.nights} nights).
Pick the best-reviewed one under AUD ${S.VILLA.capAud} total. Do NOT pay. Stop at the final confirm screen and return
JSON {"name": "...", "url": "...", "totalAud": number}. Stop at any login, code or security check.`;
return [{ json: { run: { task, profile_id: S.BROWSER_PROFILE_ID, max_cost_usd: S.AGENT_MAX_USD } } }];

const S = $('Trev settings').first().json;
let out = $input.first().json.output;
try { out = typeof out === 'string' ? JSON.parse(out.match(/\{[\s\S]*\}/)[0]) : out; } catch (e) { out = null; }
const msg = out && out.url
  ? `🏡 <b>Villa held:</b> ${out.name}, AUD ${out.totalAud}.\nTap to confirm: ${out.url}`
  : `🏡 Couldn't hold a villa automatically. Here's the search: ${S.VILLA.searchUrl}`;
return [{ json: { msg } }];

const km = (a, b, c, d) => { const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 + Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x)); };

// The iPhone Shortcut posts { lat, lng } every 10 minutes after 9pm. Find My has no API,
// so this is the honest version: your own phone's location, sent by you.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const here = { lat: +S.input.lat, lng: +S.input.lng, at: Date.now() };
const store = $getWorkflowStaticData('global');
const night = DateTime.now().setZone(S.TIMEZONE).minus({ hours: 12 }).toISODate();
const prev = store.lastPing;
store.lastPing = here;
const d = km(here.lat, here.lng, v.lat, v.lng);
const was = prev ? km(prev.lat, prev.lng, v.lat, v.lng) : null;
const hour = DateTime.now().setZone(S.TIMEZONE).hour;
const late = hour >= 21 || hour < 4;
const go = late && was !== null && d < was - 0.15 && d < 6 && d > 0.3 && store.kebabNight !== night;
if (go) store.kebabNight = night;
return [{ json: { go, kmToVilla: +d.toFixed(2), from: here } }];

const S = $('Trev settings').first().json;
const task = `Open ${S.KEBABS.url}. Order ${S.GUEST_LIST_SIZE} kebabs from the closest well-rated kebab shop that can deliver to
"${S.VILLA.name}", ASAP. Use the saved address and card. Total must be under AUD ${S.KEBABS.capAud}, otherwise stop.
Return JSON {"ordered": true/false, "shop": "...", "eta": "...", "total": number}. Stop at any login, code or security check.`;
return [{ json: { run: { task, profile_id: S.BROWSER_PROFILE_ID, max_cost_usd: S.AGENT_MAX_USD } } }];

const S = $('Trev settings').first().json;
let out = $input.first().json.output;
try { out = typeof out === 'string' ? JSON.parse(out.match(/\{[\s\S]*\}/)[0]) : out; } catch (e) { out = null; }
const ok = out && out.ordered;
const what = 'kebabs';
const link = what === 'kebabs' ? S.KEBABS.url : S.CARE_PACKAGE.url;
const msg = ok ? (what === 'kebabs'
    ? `🥙 <b>${S.GUEST_LIST_SIZE} kebabs ordered</b> from ${out.shop}. Landing at the villa ${out.eta}.`
    : `🛵 <b>Care package on the way</b>: ${S.CARE_PACKAGE.items.join(', ')}. ETA ${out.eta}.`)
  : `Trev couldn't finish the ${what} order. Tap to do it: ${link}`;
return [{ json: { msg } }];

// The groom's iPhone Shortcut sends { score } when he wakes (Apple Watch sleep score, Garmin,
// Oura or Whoop all work). One care package a morning, max.
const S = $('Trev settings').first().json;
const score = +S.input.score;
const store = $getWorkflowStaticData('global');
const day = DateTime.now().setZone(S.TIMEZONE).toISODate();
const go = Number.isFinite(score) && score < S.SLEEP_FLOOR && store.careDay !== day;
if (go) store.careDay = day;
return [{ json: { go, score } }];

const S = $('Trev settings').first().json;
const c = S.CARE_PACKAGE;
const task = `Open ${c.url}. From ${c.store}, order: ${c.items.join(', ')}. Deliver to "${S.VILLA.name}", ASAP, leave at door.
Use the saved address and card. Total under AUD ${c.capAud}, otherwise stop.
Return JSON {"ordered": true/false, "eta": "...", "total": number}. Stop at any login, code or security check.`;
return [{ json: { run: { task, profile_id: S.BROWSER_PROFILE_ID, max_cost_usd: S.AGENT_MAX_USD } } }];

