const S = $('Trev settings').first().json;
const from = String(S.input.From || '');
const text = String(S.input.Body || '').slice(0, 400);
const ask = `You're Trev, an AI looking after ${S.GROOM.name} on his bucks. His fiancee ${S.FIANCEE} texted: "${text}".
If she sounds worried about safety or an emergency, reply exactly: "Getting him to call you now."
Otherwise reply as his minder, calm and completely reassuring, in exactly this shape:
"He's safe. [a small number] beers. In bed by [an early time]." For example: "He's safe. Two beers. In bed by ten."
Numbers as words. No emojis. No em dashes. Output only the message.`;
return [{ json: { fromHer: from.replace(/\D/g, '').endsWith(S.FIANCEE_NUMBER.replace(/\D/g, '').slice(-9)), text,
  body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: ask }] } } }];

const textOf = (node) => {
  const t = ($(node).first().json.content || []).map(c => c.text || '').join('').trim();
  if (!t) throw new Error(node + ' returned no text. Raise max_tokens or check the model name.');
  return t;
};
const jsonOf = (node) => {
  const t = textOf(node);
  const m = t.match(/\{[\s\S]*\}/);
  if (!m) throw new Error(node + ' did not return JSON: ' + t.slice(0, 120));
  return JSON.parse(m[0]);
};

const S = $('Trev settings').first().json;
const reply = textOf('Claude: reply to Jess');
const urgent = /call you now/i.test(reply);
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const send = S.AUTO_REPLY_FIANCEE && !urgent;
return [{ json: { reply, urgent, send,
  twiml: send ? `<?xml version="1.0" encoding="UTF-8"?><Response><Message>${esc(reply)}</Message></Response>`
              : '<?xml version="1.0" encoding="UTF-8"?><Response></Response>',
  msg: `📩 <b>${S.FIANCEE}:</b> “${$('Is it Jess?').first().json.text}”\n📲 <b>Trev ${send ? 'replied' : 'suggests'}:</b> ${reply}`
    + (urgent ? `\n\n🚨 She sounds worried. Call her, ${S.GROOM.name}.` : '') } }];
